 test('client cannot self activate or inject flag fields',async()=>{await post('/beta/activate',{state:'ACTIVE_BETA'}).expect(404);await post('/beta/acknowledge',{privacy:true,terms:true,BETA_ALLOW_REAL_MEDIA:true}).expect(400);});
 test('normal registration blocked and rate protection remains global',async()=>{await post('/auth/register',{email:randomUUID()+'@example.invalid',password:secret}).expect(403);process.env.AUTH_IP_LIMIT='1';try{const first=await post('/beta/redeem',{email:'generated@example.invalid',password:secret,capability:randomBytes(32).toString('base64url')});assert.ok([202,429].includes(first.status));await post('/beta/redeem',{email:'generated@example.invalid',password:secret,capability:randomBytes(32).toString('base64url')}).expect(429);}finally{delete process.env.AUTH_IP_LIMIT;}});
 test('unverified account cannot acknowledge or activate',async()=>{await prepare();await gates();await pool.query('UPDATE users SET email_verified_at=NULL WHERE id=$1',[user.id]);await assert.rejects(beta.acknowledge(user.p,{privacy:true,terms:true}));await assert.rejects(beta.transition(operator,user.id,{state:'ACTIVE_BETA',reason:'SUPPORT_REQUEST'}));});
