 test('READ_ONLY_OPS cannot create invite',async()=>await assert.rejects(beta.invite(readonly,{email:randomUUID()+'@example.invalid',reason:'SUPPORT_REQUEST'})));
 test('user cap is serialized across racing approvals',async()=>{await prepare(user);await prepare(other);await gates();process.env.BETA_MAX_USERS='1';const r=await Promise.allSettled([beta.transition(operator,user.id,{state:'ACTIVE_BETA',reason:'SUPPORT_REQUEST'}),beta.transition(operator,other.id,{state:'ACTIVE_BETA',reason:'SUPPORT_REQUEST'})]);assert.equal(r.filter(x=>x.status==='fulfilled').length,1);});
 test('invite and activation audit persists',async()=>{await active();const actions=(await pool.query('SELECT action FROM security_audit WHERE target_id=$1',[user.id])).rows.map(r=>r.action);assert.ok(actions.includes('BETA_ACCOUNT_TRANSITION'));assert.ok((await pool.query("SELECT id FROM security_audit WHERE action='BETA_INVITE_CREATED'")).rowCount);});
 test('real-media flag blocks even a client labeled test upload',async()=>{await active();await assert.rejects(uploads.create(user.p,payload(),randomUUID()));});
 for(const gate of ['B2','IPHONE','STAFF_MFA','EMAIL','WORKERS','BACKUP','ALERTS','LEGAL'])test('missing '+gate+' blocks backup',async()=>{await active();allowMedia();await pool.query('UPDATE beta_acceptance SET status=\'PENDING\' WHERE gate=$1',[gate]);await assert.rejects(uploads.create(user.p,payload(),randomUUID()));});
 test('case encoded and trailing slash paths cannot bypass checkout or version policy',async()=>{await active();await post('/BILLING/CHECKOUT',{}).expect(403);await post('/billing/checkout/',{}).expect(403);allowMedia();process.env.BETA_MIN_APP_VERSION='1.0.0';await post('/UPLOADS',{}).set('X-App-Version','0.9.0').expect(403);const r=await uploads.create(user.p,payload(),randomUUID()),encoded=r.id.replace(/./,c=>'%'+c.charCodeAt(0).toString(16));await post('/uploads/'+encoded+'/start',{}).set('X-App-Version','0.9.0').expect(403);});
