 test('physical destructive gate does not silently enable cleanup',async()=>{await active();process.env.BETA_ALLOW_FREE_UP_SPACE='true';await assert.rejects(policy.startup());});
 for(const switchName of ['uploads','multipart'])test('kill switch '+switchName+' prevents authorization without deleting metadata',async()=>{await active();allowMedia();await beta.switch(operator,{name:switchName,blocked:true,reason:'SECURITY_INCIDENT'});await assert.rejects(uploads.create(user.p,payload(100,switchName==='multipart'),randomUUID()));assert.equal((await pool.query('SELECT protected_bytes FROM development_entitlements WHERE user_id=$1',[user.id])).rows[0].protected_bytes,'0');});
 test('registration and activation kill switches enforce server policy',async()=>{await beta.switch(operator,{name:'registration',blocked:true,reason:'SECURITY_INCIDENT'});await assert.rejects(beta.invite(operator,{email:randomUUID()+'@example.invalid',reason:'SUPPORT_REQUEST'}));await post('/beta/redeem',{email:user.email,password:secret,capability:randomBytes(32).toString('base64url')}).expect(503);});
 for(const cap of ['BETA_MAX_STORAGE_BYTES','MAX_USER_STORAGE_BYTES','MAX_SINGLE_FILE_SIZE','MAX_DAILY_UPLOAD_BYTES'])test('upload enforces '+cap,async()=>{await active();allowMedia();process.env[cap]='50';await assert.rejects(uploads.create(user.p,payload(100),randomUUID()));assert.equal((await pool.query('SELECT reserved_bytes FROM development_entitlements WHERE user_id=$1',[user.id])).rows[0].reserved_bytes,'0');});
 test('storage cap race permits only one reservation',async()=>{await active(user);await active(other);allowMedia();const bytes=(await pool.query('SELECT COALESCE(sum(protected_bytes+reserved_bytes),0)::text b FROM development_entitlements')).rows[0].b;process.env.BETA_MAX_STORAGE_BYTES=String(BigInt(bytes)+100n);const r=await Promise.allSettled([uploads.create(user.p,payload(),randomUUID()),uploads.create(other.p,payload(),randomUUID())]);assert.equal(r.filter(x=>x.status==='fulfilled').length,1);});
